/* Ideal RHS section geometry and explicit preliminary material assumptions. */
(function(root){'use strict';
// Ideal sharp-corner RHS, vertical depth h. No catalogue capacity is implied.
function section(code){const dims={rhs40:[40,40,2],rhs60:[60,40,2],rhs80:[80,40,2]}[code];if(!dims)return null;const [h,b,t]=dims,area=b*h-(b-2*t)*(h-2*t),I=(b*h**3-(b-2*t)*(h-2*t)**3)/12;return {h,b,t,I:I/10000,Z:I/(h/2)/1000,mass:area*7850/1e6,name:`RHS ${h}×${b}×${t} mm`};}
function preliminary(x){const sec=section(x.beamPreset);if(!sec||!Number.isFinite(x.safety)||x.safety<1.5||x.safety>5)throw Error('input:safety');return {...sec,E:200000,rodAllow:240/x.safety,beamAllow:235/x.safety,rodGrade:'4.6 · fy = 240 MPa (assumed)',beamProfile:sec.name+' · h vertical · S235 (assumed)'};}
function quick(x,engine=root.HVACDuctwork){const values={},side=Math.max(x.a,x.b);if(x.thicknessMode==='auto'&&x.shape==='rect'&&x.material==='steel'&&side>=100&&side<=4000)values.t=side<=400?.6:side<=800?.8:side<=2000?1:1.2;if(x.spanMode==='auto'){const width=x.a+2*x.insulation+2*x.clearance;if(!Number.isFinite(width)||width<=0||width>6000)throw Error('input:clearance');values.span=Math.max(.1,Math.ceil(width/50-1e-10)*.05);values.span=Number(values.span.toFixed(3));}if(x.componentMode==='auto'&&x.supportBasis==='preliminary'){const beams=['rhs40','rhs60','rhs80'],rods=['M8','M10','M12','M16','M20'];const trial=(beamPreset,rod)=>{const v=preliminary({...x,beamPreset});return engine.supports({...x,...values,beamPreset,rod,I:v.I,Z:v.Z,E:v.E,beamMass:v.mass,rodAllow:v.rodAllow,beamAllow:v.beamAllow});};let beamPreset=beams.at(-1);for(const candidate of beams){const r=trial(candidate,rods[0]);if(r.beamUtil<=1&&r.deflection<=r.limit){beamPreset=candidate;break;}}let rod=rods.at(-1);for(const candidate of rods){if(trial(beamPreset,candidate).rodUtil<=1){rod=candidate;break;}}Object.assign(values,{beamPreset,rod});}return values;}
const api={section,preliminary,quick};root.HVACDuctworkReference=api;if(typeof module!=='undefined'&&module.exports)module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
